{"implementation":"def solve(case):
    # Validate required fields
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    for key in ('round_scores', 'round_targets', 'forced'):
        if key not in case:
            raise ValueError(f"Missing required field: {key}")

    round_scores = case['round_scores']
    round_targets = case['round_targets']
    forced = case['forced']

    if not round_scores or not round_targets:
        raise ValueError("round_scores or round_targets empty")
    R = len(round_scores)
    if len(round_targets) != R:
        raise ValueError("round_targets length mismatch")
    N = len(round_scores[0])
    # Validate each round_scores list length consistent
    for scores in round_scores:
        if len(scores) != N:
            raise ValueError("inconsistent round_scores lengths")
    # Validate forced indices
    for idx in forced:
        if not (0 <= idx < N):
            raise ValueError(f"forced index {idx} out of range")
    if len(set(forced)) != len(forced):
        raise ValueError("forced indices contain duplicates")

    # Validate each round_target is non-negative? Assume positive
    # Start with all indices active
    active = list(range(N))
    history = []

    for r in range(R):
        target = round_targets[r]
        scores = round_scores[r]
        # Check feasibility
        if len(forced) > target:
            raise ValueError(f"Forced count ({len(forced)}) exceeds target ({target}) in round {r}")
        # Ensure forced indices are still in active (they should be, but check)
        for idx in forced:
            if idx not in active:
                raise ValueError(f"Forced index {idx} not in active set at round {r}")
        # Non-forced active candidates
        candidates = [i for i in active if i not in forced]
        # Number to select from candidates
        k = target - len(forced)
        if k > len(candidates):
            raise ValueError(f"Not enough candidates (have {len(candidates)}, need {k}) in round {r}")
        if k < 0:
            raise ValueError(f"Negative selection count in round {r}")
        # Sort candidates by descending score, then ascending index
        candidates_sorted = sorted(candidates, key=lambda i: (-scores[i], i))
        selected = candidates_sorted[:k]
        # Combine forced and selected, then sort to preserve original order
        new_active = sorted(forced + selected)
        active = new_active
        history.append(list(active))  # copy

    retained_indices = list(active)  # copy
    return {"history": history, "retained_indices": retained_indices}
"}
